#!/usr/bin/env node
import { existsSync } from 'fs';
import path from 'path';
import process from 'process';
import { fileURLToPath, pathToFileURL } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const distEntry = path.resolve(__dirname, 'dist', 'index.js');
const distBin = path.resolve(__dirname, 'dist', 'gitcli.js');
const srcEntry = path.resolve(__dirname, 'src', 'index.ts');

async function run() {
  if (existsSync(distBin)) {
    await import(pathToFileURL(distBin).toString());
    return;
  }
  if (existsSync(distEntry)) {
    await import(pathToFileURL(distEntry).toString());
    return;
  }
  console.error('Build output not found in the installed package. Reinstall gitcli or run `npm run build` from source.');
  process.exit(1);
}

run();
